    if (str == null) {
        return null;
    }
    try {
        return new StringBuilder(str).reverse().toString();
    } catch (Exception e) {
        // This block is defensive; in practice StringBuilder.reverse() does not throw,
        // but we guard against unexpected runtime exceptions.
        throw new IllegalArgumentException("Failed to reverse string", e);
    }
}

