public static Character[] nullToEmpty(final Character[] array) {
    // Return a shared empty array if the input is null or empty
    if (array == null || array.length == 0) {
        // It's preferable to reuse a shared empty array to save memory.
        // This array is lazily created once; it's immutable by design.
        final Character[] EMPTY_ARRAY = new Character[0];
        return EMPTY_ARRAY;
    }
    return array;
}

