public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    // Determine the horizontal bounds of the original box
    double minX = box.getMinX();
    double maxX = box.getMaxX();
    double minY = box.getMinY();
    double maxY = box.getMaxY();

    // Compute the x-coordinate that splits the box into two equal halves
    double midX = (minX + maxX) * 0.5;

    // Create the two resulting boxes
    Box2D left  = new Box2D(minX, minY, midX - minX, maxY - minY);
    Box2D right = new Box2D(midX, minY, maxX - midX, maxY - minY);

    // Return them as a pair
    return new Pair<>(left, right);
}

