    if (v == null) {
        return 0.0;
    }
    double sum = 0.0;
    try {
        for (V vertex : v) {
            if (vertex == null) {
                continue;
            }
            if (!graph.containsVertex(vertex)) {
                continue;
            }
            for (Object eObj : graph.incomingEdgesOf(vertex)) {
                @SuppressWarnings("unchecked")
                E e = (E) eObj;
                sum += graph.getEdgeWeight(e);
            }
        }
    } catch (Exception ex) {
        // In case of any unexpected errors, return 0.0 as a safe default
        return 0.0;
    }
    return sum;
