protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        return null;
    }
    if (tour.isEmpty()) {
        return null;
    }

    java.util.Set<E> remaining = new java.util.HashSet<>(tour);
    java.util.Iterator<E> iterator = remaining.iterator();
    E firstEdge = iterator.next();
    remaining.remove(firstEdge);

    java.util.List<E> orderedEdges = new java.util.ArrayList<>();
    orderedEdges.add(firstEdge);

    V startVertex = graph.getEdgeSource(firstEdge);
    V currentVertex = graph.getEdgeTarget(firstEdge);

    // Try to follow the tour in one direction
    while (!remaining.isEmpty()) {
        boolean found = false;
        for (E e : remaining) {
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex) || tgt.equals(currentVertex)) {
                orderedEdges.add(e);
                remaining.remove(e);
                currentVertex = src.equals(currentVertex) ? tgt : src;
                found = true;
                break;
            }
        }
        if (!found) {
            break;
        }
    }

    // If some edges remain, attempt to follow the tour from the start vertex in the other direction
    if (!remaining.isEmpty()) {
        currentVertex = startVertex;
        while (!remaining.isEmpty()) {
            boolean found = false;
            for (E e : remaining) {
                V src = graph.getEdgeSource(e);
                V tgt = graph.getEdgeTarget(e);
                if (src.equals(currentVertex) || tgt.equals(currentVertex)) {
                    orderedEdges.add(e);
                    remaining.remove(e);
                    currentVertex = src.equals(currentVertex) ? tgt : src;
                    found = true;
                    break;
                }
            }
            if (!found) {
                break;
            }
        }
    }

    if (!remaining.isEmpty() || orderedEdges.isEmpty()) {
        return null;
    }

    double weight = 0.0;
    try {
        for (E e : orderedEdges) {
            weight += graph.getEdgeWeight(e);
        }
    } catch (Exception ignored) {
        // Edge weights may not be defined; ignore if unavailable
    }

    try {
        return new GraphPath<V, E>(graph, startVertex, currentVertex, weight, orderedEdges);
    } catch (Throwable t) {
        return null;
    }
}

