    List<E> edges = new ArrayList<>();
    Set<E> visited = new HashSet<>();

    vertices.add(startVertex);
    edges.add(startEdge);
    visited.add(startEdge);
    double weight = graph.getEdgeWeight(startEdge);

    // Determine whether the graph is directed (assumes JGraphT)
    boolean directed = graph.getType().isDirected();

    while (visited.size() < tour.size()){
        boolean found = false;
        for (E e : tour){
            if (visited.contains(e)) continue;
            if (directed){
                if (graph.getEdgeSource(e).equals(currentVertex)){
                    currentVertex = graph.getEdgeTarget(e);
                    vertices.add(currentVertex);
                    edges.add(e);
                    visited.add(e);
                    weight += graph.getEdgeWeight(e);
                    found = true;
                    break;
                }
            } else {
                V u = graph.getEdgeSource(e);
                V v = graph.getEdgeTarget(e);
                if (u.equals(currentVertex) || v.equals(currentVertex)){
                    V next = u.equals(currentVertex) ? v : u;
                    currentVertex = next;
                    vertices.add(next);
                    edges.add(e);
                    visited.add(e);
                    weight += graph.getEdgeWeight(e);
                    found = true;
