                graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        currentVertex = other;
        vertexList.add(currentVertex);
    }

    // If the path is a cycle, close it by adding the start vertex at the end
    if (!vertexList.isEmpty()){
        V first = vertexList.get(0);
        if (!vertexList.get(vertexList.size() - 1).equals(first)){
