private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices must not be null.");
    }

    // A single vertex or empty set is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    for (V v1 : vertices) {
        // ensure vertex is part of the graph
        if (!graph.containsVertex(v1)) {
            return false;
        }
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            if (!graph.containsVertex(v2)) {
                return false;
            }
            // For undirected graphs, getEdge(v1, v2) and getEdge(v2, v1) return the same edge
            if (graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

