public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return null;
    }
    boolean isAbsolute = path.startsWith("/");
    String[] pathParts = path.split("/");
    String[] relParts = relativePath.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    if (isAbsolute) {
        stack.offerLast(""); // placeholder for leading slash
    }
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("")) {
                stack.pollLast();
            } else if (!isAbsolute) {
                stack.offerLast(part);
            }
        } else {
            stack.offerLast(part);
        }
    }
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("")) {
                stack.pollLast();
            } else if (!isAbsolute) {
                stack.offerLast(part);
            }
        } else {
            stack.offerLast(part);
        }
    }
    StringBuilder result = new StringBuilder();
    for (String comp : stack) {
        if (comp.isEmpty()) { // leading slash
            result.append("/");
            continue;
        }
        if (result.length() > 0) {
            result.append("/");
        }
        result.append(comp);
    }
    if (result.length() == 0) {
        return isAbsolute ? "/" : ".";
    }
    return result.toString();
}

