public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    try {
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path rel = java.nio.file.Paths.get(relativePath);
        java.nio.file.Path resolved = base.resolve(rel).normalize();
        String result = resolved.toString();
        // Convert OS-specific separators to forward slashes
        result = result.replace(java.io.File.separatorChar, '/');
        // Collapse multiple consecutive slashes
        result = result.replaceAll("/{2,}", "/");
        return result;
    } catch (Exception e) {
        // Fallback simple concatenation if Path API fails
        if (relativePath.startsWith("/") || relativePath.startsWith(java.io.File.separator)) {
            return relativePath.replace(java.io.File.separatorChar, '/');
        }
        String base = path.endsWith("/") ? path.substring(0, path.length() - 1) : path;
        String rel = relativePath.startsWith("/") || relativePath.startsWith(java.io.File.separator) ?
                     relativePath.substring(1) : relativePath;
        return base + "/" + rel;
    }
}

