            } else {
                // If relative base, keep leading '..'
                if (!isAbsolute) {
                    stack.add("..");
                }
                // If absolute base and stack empty, ignore; cannot go above root
            }
            continue;
        }
        stack.add(part);
    }

    // Apply the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                if (stack.get(stack.size() - 1).equals("..")) {
                    // Preserve consecutive '..' in a relative context
                    stack.add("..");
                } else {
                    stack.remove(stack.size() - 1);
                }
            } else {
                // If no directory to go up, preserve '..' if the base is relative
                if (!isAbsolute) {
                    stack.add("..");
                }
            }
            continue;
        }
        stack.add(part);
    }

    // Build the resulting path string
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    // Ensure that we return "/" for an absolute root path with no components
    if (result.length() == 0 && isAbsolute) {
        result.append("/");
    }

    return result.toString();
}

