            outputStream.flush();
        } else if (writer != null) {
            writer.write(formattedMessage);
            writer.flush();
        } else {
            // Fallback to standard out if no output configured
            System.out.print(formattedMessage);
        }
    } catch (Exception e) {
        // Use error handler to report the failure
        if (errorHandler != null) {
            errorHandler.error("Failed to append logging event", e, ErrorCode.WRITE_FAILURE);
        } else {
            // If no error handler is configured, rethrow as runtime
            throw new RuntimeException("Failed to append logging event", e);
        }
    }
}

