public static void createConfigurationDirectory(){
    String osName = System.getProperty("os.name");
    String basePath;
    if (osName != null && osName.equalsIgnoreCase("Windows 2000")){
        String homeDrive = System.getenv("HOMEDRIVE");
        if (homeDrive == null || homeDrive.isEmpty()){
            homeDrive = System.getProperty("user.home");
            // Trim directory part if possible
            int idx = homeDrive.lastIndexOf(System.getProperty("file.separator"));
            if (idx > 0){
                homeDrive = homeDrive.substring(0, idx);
            }
        }
        basePath = homeDrive + System.getProperty("file.separator") + "Documents and Settings";
    } else {
        basePath = System.getProperty("user.home");
    }
    if (basePath == null){
        return; // nothing to do
    }
    File configDir = new File(basePath, "lf5");
    try {
        if (!configDir.exists()){
            configDir.mkdirs();
        }
    } catch (SecurityException e){
        // silently ignore; caller may handle missing permissions
    }
}

