                        i++;
                    }
                    // skip underlying type
                    if (i < descriptor.length()){
                        if (descriptor.charAt(i) == 'L'){ // object after array
                            i++;                      // skip 'L'
                            while (i < descriptor.length() && descriptor.charAt(i) != ';'){
                                i++;
                            }
                            if (i < descriptor.length()) i++; // skip ';'
                        } else {
                            i++;                      // primitive type
                        }
                    }
                    slots += 1;
                } else if (descriptor.charAt(i) == 'L'){ // object type
                    i++;                                  // skip 'L'
                    while (i < descriptor.length() && descriptor.charAt(i) != ';'){
                        i++;
                    }
                    if (i < descriptor.length()) i++;      // skip ';'
                    slots += 1;
                } else {                                  // primitive type
                    char c = descriptor.charAt(i);
                    i++;
                    if (c == 'J' || c == 'D'){
                        slots += 2;
                    } else {
                        slots += 1;
                    }
                }
            }
        } else {                                            // field descriptor
            int i = 0;
            if (descriptor.charAt(i) == '['){                // array descriptor
                while (i < descriptor.length() && descriptor.charAt(i) == '['){
                    i++;
                }
                if (i < descriptor.length()){
