                        if (i < descriptor.length()) i++; // skip ';'
                    } else {
                        i++;                                 // primitive type
                    }
                }
                slots = 1;
            } else if (descriptor.charAt(i) == 'L'){          // object descriptor
                i++;
                while (i < descriptor.length() && descriptor.charAt(i) != ';'){
