                        int sem2 = args.indexOf(';', i);
                        if (sem2 == -1) {
                            throw new IllegalArgumentException("Malformed array object type");
                        }
                        i = sem2 + 1;
                    } else if (i < args.length()) {
                        i++;
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Unknown descriptor char: " + c);
